// The dynamic-LABEL warning, proven in a real browser — the exact case:
// a key composed at runtime, passed through the translation engine, that
// RESOLVES. The runtime knows which keys come from static call sites
// (client/js/i18n/call-sites.ts, generated by tools/i18n/compile.ts) and
// warns for any key outside that set — once per key, in ANY language,
// whether or not the lookup succeeds. Under en AND de:
//
//   1. the dev console announces the diagnostics at boot (never silent);
//   2. seanceI18n.t("bogus" + ".key") — composed, unresolved — warns as a
//      DYNAMIC LABEL and as a missing key;
//   3. t(`prefix.${x}`) template-style composition warns the same way;
//   4. an assembled key THAT RESOLVES (catalog-only key) warns too;
//   5. a genuine static call site stays silent through the whole run.
//
//   NODE_ENV=development corepack yarn i18n:compile && corepack yarn build:client
//   python3 -m http.server -d public 8000 &
//   CHROME_BIN=$PWD/tmp/chrome-headless-wrapper.sh \
//     node tools/browser-drive.mjs tools/scenarios/i18n-dynamic-keys.mjs
export const url = "http://127.0.0.1:8000/";

const wrapWarn = `window.__warns = [];
	console.warn = ((orig) => (...a) => { window.__warns.push(a.join(" ")); orig(...a); })(console.warn);
	console.info = ((orig) => (...a) => { window.__warns.push("INFO " + a.join(" ")); orig(...a); })(console.info);`;

const reloadAs = async (page, locale) => {
	await page.evaluate(
		`localStorage.setItem("settings", JSON.stringify({locale: ${JSON.stringify(locale)}}))`
	);
	await page.evaluate(`(() => { window.__preReload = true; })()`);
	await page.send("Page.reload");
	const started = Date.now();

	for (;;) {
		try {
			if (
				await page.evaluate(
					`!window.__preReload && document.documentElement.lang === ${JSON.stringify(
						locale
					)} && !!document.querySelector("#connect form")`
				)
			) {
				return;
			}
		} catch {
			// the document is being replaced
		}

		if (Date.now() - started > 20000) {
			throw new Error(`timed out waiting for ${locale} after reload`);
		}

		await page.sleep(150);
	}
};

const leg = async (page, locale) => {
	await reloadAs(page, locale);
	const warns = await page.evaluate(`window.__warns ?? []`);

	// (1) The dev console announces the diagnostics — never silent.
	page.check(
		`${locale}: boot announces the diagnostics`,
		warns.some((line) => line.includes("developer diagnostics armed"))
	);

	// NOTE: the composed keys here are deliberately keys NO static call
	// site resolves (bogus.key, fake.joined, mode.op). A composition that
	// lands exactly on an existing static call site's key is
	// indistinguishable from that call site by key identity — the build-time
	// assembled-site tracker (tools/i18n/check.ts) covers that half.
	const haul = await page.evaluate(
		`(() => {
			window.__warns = window.__warns || [];
			window.__warns.length = 0;
			window.seanceI18n.t("bogus" + ".key");          // composed, unresolved
			window.seanceI18n.t(["fake.", "joined"].join("")); // composed, unresolved
			window.seanceI18n.t(\`mode.\${"op"}\`);           // template-style
			window.seanceI18n.t("connect.submit");           // static literal
			return window.__warns;
		})()`
	);
	page.check(
		`${locale}: composed key warns as a dynamic label`,
		haul.some((line) => line.includes("dynamic label") && line.includes('"bogus.key"'))
	);
	page.check(
		`${locale}: joined key warns as a dynamic label`,
		haul.some((line) => line.includes("dynamic label") && line.includes('"fake.joined"'))
	);
	page.check(
		`${locale}: template-style key warns as a dynamic label`,
		haul.some((line) => line.includes("dynamic label") && line.includes('"mode.op"'))
	);
	page.check(
		`${locale}: a static literal warns nothing at all`,
		!haul.some((line) => line.includes('"connect.submit"') && line.includes("dynamic label"))
	);
	return haul;
};

export default async function main(page) {
	// bundle.js?v=dev is a stable URL; never let Chromium heuristically
	// cache it in this scenario.
	await page.send("Network.enable");
	await page.send("Network.setCacheDisabled", {cacheDisabled: true});
	// The wrapper is installed before any page script on EVERY document, so
	// the boot announcements and every later warning are captured across
	// reloads.
	await page.addInitScript(wrapWarn); // exported by the driver
	await page.goto(page.url, {waitForSelector: "#connect form"});

	await leg(page, "en");
	await leg(page, "de");
}
